def has_short_cycle(adj, max_length=5):
    def bfs(start):
        queue = [(start, -1, 0)]  # node, parent, dist
        visited = {start: 0}
        while queue:
            node, parent, dist = queue.pop(0)
            for nei in adj[node]:
                if nei == parent:
                    continue
                if nei in visited:
                    cycle = dist + visited[nei] + 1
                    if cycle <= max_length:
                        return True
                    continue
                visited[nei] = dist + 1
                queue.append((nei, node, dist + 1))
        return False
    for i in range(27):
        if bfs(i):
            return True
    return False

